import{_ as n,l as o,o as e,c as s,v as i,p as l,x as r,d,i as m,S as p}from"./chunks/framework.InCnrqk-.js";const v=JSON.parse('{"title":"欧拉函数与莫比乌斯","description":"","frontmatter":{"title":"欧拉函数与莫比乌斯","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/euler-mobius.md","filePath":"cs/euler-mobius.md","lastUpdated":1789023840000}'),u={name:"cs/euler-mobius.md"};function h(c,a,_,f,E,A){const t=o("Mermaid");return e(),s("div",null,[a[1]||(a[1]=i('<h1 id="欧拉函数与莫比乌斯" tabindex="-1">欧拉函数与莫比乌斯 <a class="header-anchor" href="#欧拉函数与莫比乌斯" aria-label="Permalink to &quot;欧拉函数与莫比乌斯&quot;">​</a></h1><div class="epigraph"><p>$\\varphi(n)$ 计与 $n$ 互素的剩余；$\\mu$ 在平方因子上为 0、在 $k$ 个不同素因子上为 $(-1)^k$。二者积性，可与素数同筛。</p><footer>—— 据 Euclid–Euler；Möbius；CLRS 第 31 章；[欧拉定理](/cs/fermat-euler) 对照整理</footer></div><p>上一课<a href="/cs/sieve">素数筛</a>给出最小素因子。主干<a href="/cs/fermat-euler">费马–欧拉</a>已用 \\(\\varphi\\) 于模幂。本课缺口是<strong>函数值表</strong>：积性函数随筛填 \\(\\varphi\\)、\\(\\mu\\)。不重证欧拉定理。后课 BSGS 用群阶，本课先把 \\(\\mu\\) 备好给反演。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(\\varphi(n)=n\\prod_{p\\mid n}(1-1/p)\\)。\\(\\mu(n)=0\\) 若平方因子，否则 \\((-1)^{\\omega(n)}\\)。积性：\\(m,n\\) 互素则 \\(f(mn)=f(m)f(n)\\)。线性筛：已知 \\(minp[i]\\)，可递推 \\(\\varphi(i)\\)、\\(\\mu(i)\\)。狄利克雷卷积 \\((f*g)(n)=\\sum_{d\\mid n}f(d)g(n/d)\\)。\\(\\sum_{d\\mid n}\\mu(d)=[n=1]\\)。</p><p>缺口是表与积性，不是再证 \\(a^{\\varphi(n)}\\equiv 1\\)。</p><h3 id="不是随机符号" tabindex="-1">\\(\\mu\\) 不是随机符号 <a class="header-anchor" href="#不是随机符号" aria-label="Permalink to &quot;$\\mu$ 不是随机符号&quot;">​</a></h3><p>\\(\\mu\\) 由素因子个数决定，筛出来是确定的。后课反演才用卷积逆。</p><p><span class="marginnote">CLRS 31.3–31.4 欧拉函数。Möbius 反演下一课专讲，本课先定义。后课离散对数假定知道阶。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>线性筛数组 <code>phi[]</code>、<code>mu[]</code>、<code>primes[]</code>。按 \\(p\\nmid i\\) 与 \\(p\\mid i\\) 分情况递推。单点 \\(\\varphi(n)\\)：分解 \\(n\\)，\\(O(\\sqrt n)\\)。</p>',11)),(e(),l(p,null,{default:r(()=>[m(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20MINP%5B%22%E6%9C%80%E5%B0%8F%E7%B4%A0%E5%9B%A0%E5%AD%90%22%5D%20--%3E%20PHI%5B%22%E9%80%92%E6%8E%A8%20%CF%86%22%5D%0A%20%20MINP%20--%3E%20MU%5B%22%E9%80%92%E6%8E%A8%20%CE%BC%22%5D%0A%20%20PHI%20--%3E%20TAB%5B%22%E7%A7%AF%E6%80%A7%E5%87%BD%E6%95%B0%E8%A1%A8%22%5D%0A%20%20MU%20--%3E%20TAB%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<p>前缀和 \\(\\sum_{i=1}^n\\varphi(i)\\)、\\(\\sum\\mu\\) 后课杜教筛点名。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>积性使 \\(n=\\prod p^k\\) 时函数乘起来。筛的递推正是按最小 \\(p\\) 拆。与高斯线性基无关。与生成函数：\\(\\sum\\mu(n)/n^s=1/\\zeta(s)\\) 点名，本课不进解析数论。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写杜教筛、不写 Dirichlet L。后课默认：\\(\\varphi\\)、\\(\\mu\\) 可线性筛；\\(\\mu\\) 是卷积单位的逆。下一课 BSGS 离散对数。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(\\varphi\\)、\\(\\mu\\) 积性，随线性筛填表。</li><li>\\(\\sum_{d\\mid n}\\mu(d)=[n=1]\\)。</li><li>单点可分解；表用于后课反演。</li><li>出处：CLRS 第 31 章；古典 \\(\\varphi\\)、\\(\\mu\\)。</li></ul>',7))])}const B=n(u,[["render",h]]);export{v as __pageData,B as default};
